begin;
create index if not exists card_installments_transaction_fk_idx on public.card_installments(tenant_id,company_id,transaction_id);
create index if not exists card_statement_payments_account_fk_idx on public.card_statement_payments(tenant_id,company_id,account_id);
create index if not exists card_statement_payments_card_fk_idx on public.card_statement_payments(tenant_id,company_id,card_id);
create index if not exists card_transactions_category_fk_idx on public.card_transactions(tenant_id,company_id,category_id) where category_id is not null;
create index if not exists card_transactions_cost_center_fk_idx on public.card_transactions(tenant_id,company_id,cost_center_id) where cost_center_id is not null;
create index if not exists credit_cards_payment_account_fk_idx on public.credit_cards(tenant_id,company_id,default_payment_account_id) where default_payment_account_id is not null;
create index if not exists financial_recurrence_occurrences_entry_fk_idx on public.financial_recurrence_occurrences(tenant_id,company_id,entry_id) where entry_id is not null;
create index if not exists financial_recurrence_occurrences_rule_fk_idx on public.financial_recurrence_occurrences(tenant_id,company_id,recurrence_rule_id);
create index if not exists financial_recurrence_rules_category_fk_idx on public.financial_recurrence_rules(tenant_id,company_id,category_id) where category_id is not null;
create index if not exists financial_recurrence_rules_cost_center_fk_idx on public.financial_recurrence_rules(tenant_id,company_id,cost_center_id) where cost_center_id is not null;
create index if not exists financial_transfers_from_account_fk_idx on public.financial_transfers(tenant_id,company_id,from_account_id);
create index if not exists financial_transfers_to_account_fk_idx on public.financial_transfers(tenant_id,company_id,to_account_id);
create view public.finance_operational_installments with(security_invoker=true) as select e.tenant_id,e.company_id,e.id entry_id,i.id installment_id,e.entry_type,e.description,e.counterparty_name,e.category_id,e.cost_center_id,i.competence_month,i.installment_number,i.installment_count,(i.installment_number::text||'/'||i.installment_count::text) installment_label,i.due_date,i.amount,coalesce(sum(s.amount),0)::numeric(14,2) settled_amount,greatest(i.amount-coalesce(sum(s.amount),0),0)::numeric(14,2) open_amount,case when coalesce(sum(s.amount),0)>=i.amount then 'paid' when coalesce(sum(s.amount),0)>0 then 'partial' when i.due_date<current_date then 'overdue' else 'pending' end payment_status from public.financial_entries e join public.financial_installments i on i.tenant_id=e.tenant_id and i.company_id=e.company_id and i.entry_id=e.id left join public.financial_settlements s on s.tenant_id=i.tenant_id and s.company_id=i.company_id and s.installment_id=i.id group by e.tenant_id,e.company_id,e.id,i.id;
create view public.finance_operational_cards with(security_invoker=true) as select c.tenant_id,c.company_id,c.id card_id,c.name card_name,c.credit_limit,c.status,coalesce(sum(ci.amount),0)::numeric(14,2) committed_amount,greatest(c.credit_limit-coalesce(sum(ci.amount),0),0)::numeric(14,2) estimated_available_limit from public.credit_cards c left join public.card_installments ci on ci.tenant_id=c.tenant_id and ci.company_id=c.company_id and ci.card_id=c.id group by c.tenant_id,c.company_id,c.id;
commit;
